export const W=34,H=26,T=32;
const map=(name,theme,seed)=>({name,theme,seed,tiles:Array.from({length:H},()=>Array(W).fill(theme==='village'?'g':theme==='forest'?'g':theme==='mine'?'d':'r')),objects:[],spawns:[]});
const rect=(m,x,y,w,h,t)=>{for(let j=y;j<y+h;j++)for(let i=x;i<x+w;i++)if(m.tiles[j]?.[i]!==undefined)m.tiles[j][i]=t;};
const obj=(m,id,type,x,y,extra={})=>m.objects.push({id,type,x,y,...extra});
const border=m=>{rect(m,0,0,W,2,'#');rect(m,0,H-2,W,2,'#');rect(m,0,0,2,H,'#');rect(m,W-2,0,2,H,'#');};
export function createWorld(){const village=map('ノルヴィクの町','village',3);border(village);rect(village,2,12,30,4,'p');rect(village,13,2,4,22,'p');rect(village,9,8,13,11,'p');
obj(village,'manor','house',12,3,{w:7,h:4,label:'領主館',roof:'blue'});obj(village,'innhouse','house',4,7,{w:5,h:4,label:'憩いの家',roof:'red'});obj(village,'smithhouse','house',23,7,{w:6,h:4,label:'ドーラン工房',roof:'green'});obj(village,'home1','house',4,18,{w:5,h:4,label:'町の家',roof:'blue'});obj(village,'home2','house',24,18,{w:5,h:4,label:'町の家',roof:'red'});
obj(village,'victor','npc',15,11,{name:'ヴィクトル',sprite:'elder',marker:'!'});obj(village,'inn','npc',8,12,{name:'宿の人',sprite:'woman'});obj(village,'smith','npc',24,12,{name:'リネア',sprite:'woman',marker:'⚒'});obj(village,'finn','npc',10,18,{name:'フィン',sprite:'boy',marker:'?'});obj(village,'oscar','npc',20,17,{name:'オスカー',sprite:'knight',marker:'?'});obj(village,'well','well',12,10);obj(village,'villagesign','sign',18,14,{text:'東：雪解けの森・北の坑道\n広場：ヴィクトル　西：休息　東の工房：装備と薬草'});obj(village,'forestExit','exit',31,14,{to:'forest',tx:3,ty:18,label:'雪解けの森へ'});rect(village,30,13,4,3,'p');
const forest=map('雪解けの森','forest',7);border(forest);rect(forest,2,17,29,3,'p');rect(forest,13,4,3,16,'p');rect(forest,13,4,18,3,'p');rect(forest,21,10,3,9,'p');rect(forest,6,5,5,6,'w');rect(forest,7,11,3,7,'w');rect(forest,7,17,3,3,'b');rect(forest,2,17,3,3,'p');
for(const [x,y]of [[3,3],[5,3],[12,2],[20,3],[24,3],[28,3],[3,10],[4,14],[11,12],[17,9],[19,11],[26,12],[29,10],[29,15],[5,22],[11,22],[18,22],[23,22],[29,22],[19,7]])obj(forest,`tree${x}_${y}`,'tree',x,y);
obj(forest,'villageExit','exit',2,18,{to:'village',tx:30,ty:14,label:'ノルヴィクへ'});obj(forest,'mineExit','exit',29,5,{to:'mine',tx:16,ty:22,label:'北の坑道へ'});obj(forest,'ore1','ore',12,8);obj(forest,'ore2','ore',24,16);obj(forest,'herb1','herb',4,21);obj(forest,'herb2','herb',17,12);obj(forest,'herb3','herb',26,8);obj(forest,'tools','chest',29,20,{item:'tools',label:'フィンの道具袋'});obj(forest,'forestchest','chest',12,4,{item:'potions',label:'薬草 ×3'});obj(forest,'spring','spring',21,12);obj(forest,'woodsign','sign',13,16,{text:'古い道標：北の道を東へ、坑道に至る。\n澄んだ泉に触れると、体力と集中力が回復する。'});obj(forest,'f1','enemy',14,12,{enemy:'wolf'});obj(forest,'f2','enemy',21,18,{enemy:'moth'});obj(forest,'f3','enemy',26,5,{enemy:'wolf'});
const mine=map('北の坑道','mine',11);border(mine);for(let y=2;y<24;y++)for(let x=2;x<32;x++)mine.tiles[y][x]='#';rect(mine,12,17,10,7,'d');rect(mine,14,4,5,17,'d');rect(mine,5,10,24,4,'d');rect(mine,4,6,7,8,'d');rect(mine,23,8,7,10,'d');rect(mine,11,3,11,5,'d');rect(mine,14,2,5,4,'d');rect(mine,14,23,5,3,'d');
obj(mine,'forestBack','exit',16,23,{to:'forest',tx:28,ty:5,label:'雪解けの森へ'});obj(mine,'doran','npc',13,20,{name:'ドーラン',sprite:'smith',marker:'!'});obj(mine,'pump','pump',18,18);obj(mine,'ore3','ore',6,8);obj(mine,'ore4','ore',27,16);obj(mine,'minechest','chest',25,10,{item:'silver',label:'銀貨 35枚と薬草2つ'});obj(mine,'m1','enemy',12,11,{enemy:'crawler'});obj(mine,'m2','enemy',24,13,{enemy:'crawler'});obj(mine,'m3','enemy',16,8,{enemy:'moth'});obj(mine,'father','tablet',19,5,{lore:'father',title:'父の記録',text:'「北の壁は温かい。奥で一定の振動。\nだが、取り残された者がいる。調査は後だ。」\n\nユリスは、紙の端に残った煤をそっと撫でた。'});obj(mine,'ruinsExit','exit',16,3,{to:'ruins',tx:16,ty:22,label:'古代遺跡へ',lock:'pump'});obj(mine,'camp','spring',20,21);
const ruins=map('古代遺跡・予備導管','ruins',19);border(ruins);rect(ruins,3,3,28,20,'r');for(const [x,y,w,h]of [[3,3,10,2],[21,3,10,2],[3,8,9,2],[22,8,9,2],[3,15,9,2],[22,15,9,2]])rect(ruins,x,y,w,h,'#');rect(ruins,15,3,3,20,'q');rect(ruins,5,11,24,2,'q');
obj(ruins,'mineBack','exit',16,23,{to:'mine',tx:16,ty:4,label:'北の坑道へ'});obj(ruins,'lore1','tablet',13,19,{lore:'flow',title:'予備系統の石碑',text:'「まず水を通す。次に風を逃がす。\n最後に灯をともす。主幹は止めてはならない。」\n\nノア「水、風、灯の順だね。予備の通り道を作るんだよ。」'});obj(ruins,'water','valve',7,18,{label:'水の弁',symbol:'水',color:'#70c8d6'});obj(ruins,'wind','valve',26,12,{label:'風の弁',symbol:'風',color:'#a5d4ac'});obj(ruins,'light','valve',7,6,{label:'灯の弁',symbol:'灯',color:'#e3bf7d'});obj(ruins,'lore2','tablet',27,6,{lore:'keepers',title:'残された使命',text:'「我らが去った後も、大地の調整を続けよ。\n人々の暮らす地を、どうか守り続けてほしい。」\n\nエド「……ずっと、一人で守っていたのかな。」'});obj(ruins,'r1','enemy',16,16,{enemy:'sentinel'});obj(ruins,'r2','enemy',21,12,{enemy:'sentinel'});obj(ruins,'r3','enemy',12,6,{enemy:'crawler'});obj(ruins,'ruinchest','chest',27,20,{item:'relic',label:'古い守りの留め金'});obj(ruins,'ruinspring','spring',18,20);obj(ruins,'heartExit','exit',16,3,{to:'heart',tx:16,ty:21,label:'大地の心臓へ',lock:'gate'});
const heart=map('大地の心臓','heart',23);border(heart);rect(heart,3,3,28,20,'v');rect(heart,13,4,7,20,'r');rect(heart,6,10,22,6,'r');rect(heart,10,7,14,12,'r');rect(heart,15,7,3,17,'q');obj(heart,'heartBack','exit',16,23,{to:'ruins',tx:16,ty:4,label:'予備導管へ'});rect(heart,14,22,5,3,'r');obj(heart,'greatCrystal','crystal',16,5,{w:2,h:2});obj(heart,'bear','boss',16,11,{enemy:'bear',name:'熊型機霊'});obj(heart,'heartSpring','spring',19,20);obj(heart,'memory','tablet',11,16,{lore:'promise',title:'二人の約束',text:'ノア「つらくなったら、止めてって言うね。」\nユリス「うん。今度は、二人で決めよう。」\n\n共感覚は、相手を思い通りにする力ではない。\n触れ合い、望み合う間だけ、感覚の断片を分かち合う。'});
for(const m of [village,forest,mine,ruins,heart])m.objects=m.objects.filter(o=>o.type!=='enemy');
return {village,forest,mine,ruins,heart};}
export function visibleObject(o,s){return !(s.collected.includes(o.id)||s.defeated.includes(o.id)||(o.id==='bear'&&s.flags.bear));}
export function solid(m,x,y,s){if(x<0||y<0||x>=W||y>=H||['#','w','v'].includes(m.tiles[y][x]))return true;return m.objects.some(o=>visibleObject(o,s)&&['house','tree','well','crystal','pump'].includes(o.type)&&x>=o.x&&x<o.x+(o.w||1)&&y>=o.y&&y<o.y+(o.h||1));}

